def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = sum(1 for h in history if h[1] == 'D')
    opp_def_rate = opp_def / n

    last_my, last_opp = history[-1]

    if opp_def_rate > 0.8:
        return 'D'

    if last_my == 'D' and last_opp == 'C':
        return 'D'

    if last_my == 'D' and last_opp == 'D':
        return 'C'

    if last_my == 'C' and last_opp == 'D':
        if n >= 10 and opp_def_rate > 0.3:
            return 'D'
        else:
            return 'C'

    if last_my == 'C' and last_opp == 'C':
        if opp_def == 0 and n >= 3:
            return 'D'
        else:
            return 'C'

    return 'C'
